    id: "R136",
    suite: "test:packaging",
    what: "stop harvesting licence prose from READMEs",
    file: NOTICES_GEN,
    from: "  const atxLevel = (l) => {",
    to: "  const atxLevel = () => 0; const unusedAtxLevel = (l) => {",
