    // failure is a wrong ANSWER rather than a parse error.
    what: "drop the already-relocated guard from the dev-profile decision",
    file: MAIN,
    from: '  if (path.resolve(app.getPath("userData")) !== path.resolve(standard)) {',
    to: "  if (false) {",
