const argv = process.argv.slice(2);
function duplicateRevertIds(records) {
  const counts = new Map();
  for (const { id } of records) counts.set(id, (counts.get(id) || 0) + 1);
  return [...counts].filter(([, count]) => count > 1).map(([id, count]) => `${id} (${count})`);
}

function proveUniqueRevertIds() {
  const duplicateIds = duplicateRevertIds(REVERTS);
  const positive = [{ id: "R-unique-a" }, { id: "R-unique-b" }];
  const negative = [...positive, { id: "R-unique-a" }];
  const negativeIds = duplicateRevertIds(negative);
  if (
    duplicateIds.length ||
    duplicateRevertIds(positive).length ||
    negativeIds.length !== 1 ||
    negativeIds[0] !== "R-unique-a (2)"
  ) {
    console.error(
      `SELF-CHECK FAILED: revert IDs must be unique; duplicate inventory: ` +
        `${duplicateIds.length ? duplicateIds.join(", ") : "<none>"}.`,
    );
    process.exit(2);
  }
  console.log(
    `revert-ID inventory self-check OK: ${REVERTS.length} unique IDs; ` +
      "the injected duplicate was detected",
  );
}

proveUniqueRevertIds();
function additionalEdits(r) {
  if (Object.hasOwn(r, "edits")) {
    throw new Error(`Unsupported edits field in ${r.id}; compound mutations use also`);
  }
  return r.also ? (Array.isArray(r.also) ? r.also : [r.also]) : [];
}

function proveCompoundEditSchema() {
  for (const record of REVERTS) additionalEdits(record);
  const edit = { from: "control", to: "mutant" };
  const valid =
    additionalEdits({ id: "empty-control" }).length === 0 &&
    additionalEdits({ id: "single-control", also: edit })[0] === edit &&
    additionalEdits({ id: "array-control", also: [edit] })[0] === edit;
  const rejected = [
    { id: "wrong-array", edits: [edit] },
    { id: "wrong-object", edits: edit },
    { id: "mixed-fields", also: [edit], edits: [edit] },
  ].every((record) => {
    try { additionalEdits(record); }
    catch (error) {
      return error.message.includes("Unsupported edits field");
    }
    return false;
  });
  if (!valid || !rejected) {
    throw new Error("SELF-CHECK FAILED: compound mutation field discrimination");
  }
  console.log("compound-edit self-check OK: supported also forms work; unsupported edits forms are rejected");
}
proveCompoundEditSchema();
// A refactor cannot break a revert's ASSERTIONS without also running its suite,
// but it breaks a revert's ANCHOR - the text the harness perturbs - for free,
// silently, and the report only arrives hours later at the end of a full run.
// Moving files between directories does it wholesale. `--anchors` does just the
// string half of the setup for every revert and runs no suite at all, so the
// class of damage a refactor actually causes is checkable in a second.
// It is deliberately NOT a substitute for a real run: an anchor that still
// matches proves nothing about whether the assertions it is paired with still
// fail.
const anchorsOnly = argv.includes("--anchors");
// THE OTHER HALF OF ROT, and `--anchors` is structurally blind to it. A revert
// is a pair: the ANCHOR it perturbs and the ASSERTION NAMES it expects to see
// fail. Renaming an assertion breaks the second half while leaving the first
// intact, so the sweep reports "anchor OK" and the pairing is silently dead.
// Measured, not supposed: rewriting two sections of test-theme.js orphaned SEVEN
// expect regexes across R259/R265/R271/R272/R275/R276 at once.
//
// The two halves fail differently, and the `mustPass` half is the dangerous one.
// An orphaned `expect` eventually reports WRONG-GUARD - loud, but only hours
// into a full run. An orphaned `mustPass` can never match, so COLLATERAL can
// never fire and the revert reports PROVEN while its collateral guard has
// quietly stopped existing. That is this project's recurring "an assertion of
// ABSENCE fails open" disease in a new place.
//
// So this runs each referenced suite ONCE on the clean tree and checks every
// regex names a live assertion. Deliberately separate from --anchors: that is a
// one-second string sweep, this costs one suite run per distinct suite.
const expectsOnly = argv.includes("--expects");
const only = argv.filter((a) => a !== "--anchors" && a !== "--expects");
const chosen = only.length ? REVERTS.filter((r) => only.includes(r.id)) : REVERTS;
// An exception belongs only to the no-argument release run. `--anchors` and
// `--expects` are audits, not release certification; explicit IDs are how a
// deferred proof is retried without weakening any of its normal gates.
const fullHarnessReleaseRun = isFullHarnessReleaseInvocation(argv);
// Fail loud rather than silently reporting success on an empty set. A typo in
// an id (or a `--only R1,R2` that this script does not accept) otherwise ends
// with "ALL REVERTS PROVEN" having proven nothing at all - which is exactly the
// kind of vacuous green this harness exists to prevent.
if (only.length && chosen.length !== only.length) {
  const unknown = only.filter((id) => !REVERTS.some((r) => r.id === id));
  console.error(
    `Unknown revert id(s): ${unknown.join(", ")}\n` +
      `Pass bare ids, e.g. "node scripts/prove-table-fixes.js R53 R63".\n` +
      `Known ids: ${REVERTS.map((r) => r.id).join(", ")}`,
  );
  process.exit(2);
}

function runSuite(suite) {
  const virtual = VIRTUAL_SUITES[suite];
  const npmScript = virtual ? virtual.npmScript : suite || "test:tables";
  const result = spawnSync("npm", ["run", npmScript], {
    cwd: ROOT,
    encoding: "utf8",
    shell: true,
    stdio: ["ignore", "pipe", "pipe"],
    env: virtual
      ? { ...process.env, ...virtual.environment }
      : process.env,
  });
  const stdout = String(result.stdout || "");
  const stderr = String(result.stderr || "");
  // npm appends its own nonzero-exit epilogue on stderr after the suite has
  // finished. Only stdout can establish whether the suite itself ended at its
  // footer; retain stderr separately so an unterminated stdout record cannot
  // fuse with and hide a fatal stderr record.
  return {
    stdout,
    stderr,
    exitCode: typeof result.status === "number" ? result.status : 1,
    signal: typeof result.signal === "string" ? result.signal : null,
    executionError: result.error ? String(result.error) : null,
  };
}

const COMPANION_RELAY_LINE =
  /^\[companion (?:stdout|stderr)(?: (?:diagnostic|partial))?\] /;
const COMPANION_STDOUT_PROTOCOL_LINE = /^\[companion stdout\] /;
const COMPANION_TRANSCRIPT_UNUSABLE_MARKER = "=== COMPANION TRANSCRIPT UNUSABLE ===";
const LEGITIMATE_SHUTDOWN_TEARDOWN_LINES = Object.freeze([
  "Stopped file watching",
  "Shutdown approval renderer unusable: webContents destroyed",
]);

function transcriptLines(out) {
  return String(out || "").split(/\r\n|\r|\n/);
}

function transcriptRecords(out) {
  const text = String(out || "");
  const records = [];
  const newline = /\r\n|\r|\n/g;
  let start = 0;
  let match;
  while ((match = newline.exec(text))) {
    records.push({ line: text.slice(start, match.index), terminated: true });
    start = match.index + match[0].length;
  }
  if (start < text.length) {
    records.push({ line: text.slice(start), terminated: false });
  }
  return records;
}

function transcriptStreams(out) {
  return Array.isArray(out) ? out : [out];
}

function isCompanionRelayLine(line) {
  return COMPANION_RELAY_LINE.test(line);
}

function isCompanionStdoutProtocolLine(line) {
  return COMPANION_STDOUT_PROTOCOL_LINE.test(line);
}

function untagCompanionRelayLine(line) {
  return line.replace(COMPANION_RELAY_LINE, "");
}

function isLegitimateShutdownTeardown(lines) {
  return (
    lines.length === LEGITIMATE_SHUTDOWN_TEARDOWN_LINES.length &&
    lines.every((line, index) => line === LEGITIMATE_SHUTDOWN_TEARDOWN_LINES[index])
  );
}

function isExactShutdownTail(lines, expectedTail) {
  return (
    Array.isArray(expectedTail) &&
    lines.length === expectedTail.length &&
    lines.every((line, index) => line === expectedTail[index])
  );
}

// Only the top-level suite can complete its own run. A relayed child footer
// describes the child, not the parent whose exit and accounting this harness
// is certifying.
function topLevelTranscriptLines(out) {
  return transcriptLines(out).filter((line) => !isCompanionRelayLine(line));
}

// Revert records can name checks performed inside a companion. Keep those
// complete stdout protocol records in the assertion inventory and mutation
// matching, but remove the transport tag before comparing their assertion
// names. stderr and all diagnostic or partial tags are readable evidence, not
// assertions: accepting them would let interleaved diagnostics synthesize a
// false mutation result.
function assertionTranscriptLines(out) {
  return transcriptRecords(out)
    .filter(
      ({ line, terminated }) =>
        !isCompanionRelayLine(line) ||
        (terminated && isCompanionStdoutProtocolLine(line)),
    )
    .map(({ line }) => untagCompanionRelayLine(line));
}

function completedSuiteFooter(line) {
  const fraction = /^===\s*(\d+)\/(\d+)\s+passed(?:;\s*(\d+)\s+unavailable)?\s*===$/.exec(
    line,
  );
  if (fraction) {
    const passed = Number(fraction[1]);
    const total = Number(fraction[2]);
    return {
      kind: "fraction",
      passed,
      total,
      unavailable: Number(fraction[3] || 0),
      failures: total - passed,
    };
  }
  const summary =
    /^===\s*(\d+)\s+passed,\s*(\d+)\s+failed(?:,\s*(\d+)\s+SKIPPED(?::.*)?)?\s*===$/.exec(
      line,
    );
  if (!summary) return null;
  return {
    kind: "summary",
    passed: Number(summary[1]),
    total: null,
    unavailable: Number(summary[3] || 0),
    failures: Number(summary[2]),
  };
}

function isFatalSuiteTranscriptLine(line) {
  return (
    line === COMPANION_TRANSCRIPT_UNUSABLE_MARKER ||
    /^\s*FAIL\s+(?:harness threw|harness timed out|(?:additional )?uncaught main-process exception|no BrowserWindow was created)\b/i.test(
      line,
    ) || /^=== TIMED OUT\b.* ===$/.test(line)
  );
}

// A completed suite can intentionally exit non-zero when a revert makes an
